//! Move verified provisioning bytes and admitted cache grants into native creation ownership.
use super::*;
use crate::setup_storage::{
    VerifiedBundle, cache::NativeCachePin, cache::RuntimeCache, cache_custody::CacheFamilyId,
    provisioning_cache::ProvisioningCaches,
};
use std::{io, path::Path, sync::Arc};
use sugarsubstitute_contracts::{execution::JobContext, lifecycle::CoordinatorKey};

/// Private transport capability generated by the execution-owned provisioning listener.
/// It is never populated from presentation state and is deliberately not printable with Debug.
pub struct ProvisioningEndpoint {
    /// Exact bound loopback listener port.
    pub port: u16,
    /// Random listener capability for this authenticated worker only.
    pub token: String,
}
/// Retain source files, native consumer reference and both opaque writer grants as one launch role.
pub(crate) struct ProvisioningLaunch {
    _bundle: Arc<VerifiedBundle>,
    caches: ProvisioningCaches,
    pin: Option<NativeCachePin>,
    input_memory: Option<sugarsubstitute_contracts::execution::MemoryClaim>,
}
impl ProvisioningLaunch {
    /// Transfer input allocation funding after accepted creation claims the exact command bytes.
    pub(crate) fn transfer_input_memory(&mut self) {
        self.input_memory = None;
    }
    /// Match this launch's immutable private containment job name.
    pub(crate) fn family(&self) -> CacheFamilyId {
        self.caches.family()
    }
    /// Called only by the native registry's unique actually settled provisioning result.
    pub(crate) fn finish_settled(
        &mut self,
        pressure: crate::setup_storage::ProvisioningCachePressure,
        context: &JobContext,
    ) -> io::Result<()> {
        self.caches.finish_settled(pressure, context)?;
        if let Some(pin) = &mut self.pin {
            pin.retire_settled(context)?;
        }
        self.pin = None;
        Ok(())
    }
}
impl WindowsLaunchInput {
    /// Prepare cache grants before any process effect and retain the exact verified source bundle.
    /// Run on an admitted storage job with 16 MiB; the original input allocation transfers to the
    /// accepted creation reservation before its storage-job charge is released. No process starts.
    /// Cache paths and ceilings are selected here, independently of presentation/IPC requests.
    /// # Errors
    /// Preserves cache pressure, competing native ownership, invalid command and cancellation errors.
    pub fn provisioning(
        owner: CoordinatorKey,
        bundle: Arc<VerifiedBundle>,
        cache: &RuntimeCache,
        workspace: &Path,
        endpoint: ProvisioningEndpoint,
        environment: LaunchEnvironment,
        context: &JobContext,
    ) -> io::Result<Self> {
        let memory = context.memory().claim(1024 * 1024).map_err(io::Error::other)?;
        if endpoint.port == 0
            || endpoint.token.len() != 64
            || !endpoint.token.bytes().all(|byte| byte.is_ascii_hexdigit())
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "Provisioning endpoint is invalid",
            ));
        }
        let caches = ProvisioningCaches::prepare(cache, bundle.digest(), context)?;
        let environment = caches.environment(&environment)?;
        let pin = bundle.bind_native_cache(caches.family(), context)?;
        let worker = bundle.worker()?;
        let mut arguments = worker.arguments().to_vec();
        arguments.extend([
            "--setup-workspace".into(),
            workspace.as_os_str().to_owned(),
            "--setup-port".into(),
            endpoint.port.to_string().into(),
            "--setup-token".into(),
            endpoint.token.into(),
        ]);
        arguments.extend(caches.arguments()?);
        let command =
            WindowsLaunchCommand::from_os(worker.executable(), worker.directory(), &arguments)
                .map_err(io::Error::other)?;
        let mut input = Self::new(command, environment).map_err(io::Error::other)?;
        input.preparation = Some(Box::new(PreparationLaunch {
            owner,
            payload: PreparationPayload::Provisioning(Box::new(ProvisioningLaunch {
                _bundle: bundle,
                caches,
                pin,
                input_memory: Some(memory),
            })),
        }));
        Ok(input)
    }
    /// Retain native metadata access from this exact prepared provisioning family.
    /// No filesystem work occurs. Release every clone and transfer before family finalization.
    /// # Errors
    /// Rejects unrelated launch roles; presentation state and worker paths grant no access.
    pub fn provisioning_metadata(&self) -> io::Result<crate::setup_storage::ProvisioningMetadata> {
        self.preparation
            .as_ref()
            .and_then(|launch| launch.provisioning())
            .map(|launch| launch.caches.metadata())
            .ok_or_else(|| io::Error::other("Provisioning metadata role absent"))
    }
    /// Retain native download access from this exact prepared provisioning family.
    /// No filesystem work occurs; all clones must retire before actual family finalization.
    /// # Errors
    /// Rejects unrelated launch roles; JSON paths and presentation state cannot create this grant.
    pub fn provisioning_downloads(
        &self,
    ) -> io::Result<crate::setup_storage::ProvisioningDownloads> {
        self.preparation
            .as_ref()
            .and_then(|launch| launch.provisioning())
            .map(|launch| launch.caches.downloads())
            .ok_or_else(|| io::Error::other("Provisioning download role absent"))
    }
}
